/// One host-service call result. The payload points into the caller's
/// response buffer and is empty unless the transport status is zero.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ServiceReply<'a> {
    /// The transport status returned by the service module.
    pub status: i32,
    /// The bytes the host copied into the response buffer.
    pub payload: &'a [u8],
}

impl<'a> ServiceReply<'a> {
    /// Reports whether the call completed at the transport layer.
    pub const fn is_ok(self) -> bool { self.status == 0 }

    /// Returns the typed transport status, or None for an unknown code.
    pub const fn transport(self) -> Option<ServiceStatus> {
        ServiceStatus::from_code(self.status)
    }
}

