#[cfg(not(target_arch = "wasm32"))]
/// Native-test host functions used when the bindings are compiled for a
/// test harness instead of wasm32.
pub mod host {
    use std::sync::Mutex;

    /// The host side of every generated import.
    pub trait Host: Send {
        /// Returns the host ABI version.
        fn abi_version(&mut self) -> i32;
        /// Receives one guest log line.
        fn log(&mut self, level: i32, message: &[u8]);
        /// Returns the virtual clock in Unix nanoseconds.
        fn now_ns(&mut self) -> i64;
        /// Fills the buffer with deterministic random bytes.
        fn random_get(&mut self, buffer: &mut [u8]) -> i32;
        /// Captures visible output.
        fn output_write(&mut self, data: &[u8]) -> i32;
        /// Answers one host-service call and returns its transport status.
        fn service_call(&mut self, service: &str, method_id: u32,
                        request: &[u8], response: &mut [u8]) -> i32;
        /// Returns the bytes copied by the last successful service call.
        fn service_response_len(&mut self) -> u32;
        /// Delivers one language-provider response payload.
        fn language_respond(&mut self, request_id: u64, payload: &[u8]) -> i32;
        /// Reports whether one language call was cancelled.
        fn language_cancelled(&mut self, request_id: u64) -> i32;
        /// Delivers one MCP tool result payload.
        fn mcp_tool_result(&mut self, request_id: u32, payload: &[u8]) -> i32;
        /// Delivers one MCP progress notification.
        fn mcp_tool_progress(&mut self, request_id: u32, progress: u32,
                             message: &[u8]) -> i32;
        /// Delivers one cross-plugin service response payload.
        fn service_respond(&mut self, request_id: u64, payload: &[u8]) -> i32;
        /// Delivers one connection-provider response payload.
        fn provider_respond(&mut self, request_id: u64, payload: &[u8]) -> i32;
        /// Reports whether one provider call was cancelled.
        fn provider_cancelled(&mut self, request_id: u64) -> i32;
        /// Reads available provider input into the buffer.
        fn provider_input_read(&mut self, stream: u32, buffer: &mut [u8]) -> i32;
        /// Returns the available provider input credit.
        fn provider_input_credit(&mut self, stream: u32) -> i32;
        /// Writes bytes to one provider output queue.
        fn provider_output_write(&mut self, stream: u32, data: &[u8]) -> i32;
        /// Returns the available provider output credit.
        fn provider_output_credit(&mut self, stream: u32) -> i32;
        /// Delivers one data-provider response payload.
        fn data_provider_respond(&mut self, request_id: u64, payload: &[u8]) -> i32;
        /// Reports whether one data-provider call was cancelled.
        fn data_provider_cancelled(&mut self, request_id: u64) -> i32;
    }

    static INSTALLED: Mutex<Option<Box<dyn Host>>> = Mutex::new(None);

    /// Installs the host used by native bindings and returns the previous
    /// one, if any.
    pub fn install(host: Box<dyn Host>) -> Option<Box<dyn Host>> {
        let mut slot = INSTALLED.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
        slot.replace(host)
    }

    /// Removes the installed host.
    pub fn uninstall() -> Option<Box<dyn Host>> {
        let mut slot = INSTALLED.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
        slot.take()
    }

    /// Runs the closure with the installed host. Host methods must not
    /// re-enter this function.
    pub fn with<T>(f: impl FnOnce(&mut dyn Host) -> T) -> Option<T> {
        let mut slot = INSTALLED.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
        slot.as_mut().map(|host| f(host.as_mut()))
    }
}

