pub const EXPORT_LANGUAGE_REQUEST: &str = "natcatty_language_request";
pub const EXPORT_LANGUAGE_CANCEL: &str = "natcatty_language_cancel";
pub const EXPORT_SERVICE_REQUEST: &str = "natcatty_service_request";
pub const EXPORT_PROVIDER_REQUEST: &str = "natcatty_provider_request";
pub const EXPORT_DATA_PROVIDER_REQUEST: &str = "natcatty_data_provider_request";

/// Returned when the host speaks a different wire ABI.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum AbiMismatch {
    /// The host's ABI version, which these bindings do not support.
    HostAbi(i32),
    /// The guest's ABI version, which the host does not support.
    GuestAbi(i32),
}

impl core::fmt::Display for AbiMismatch {
    fn fmt(&self, f: &mut core::fmt::Formatter<'_>) -> core::fmt::Result {
        match *self {
            AbiMismatch::HostAbi(host) => {
                write!(f, "plugin ABI {} is not supported (bindings speak {})", host, ABI_VERSION)
            }
            AbiMismatch::GuestAbi(guest) => {
                write!(f, "guest ABI {} is not supported (host speaks {})", guest, ABI_VERSION)
            }
        }
    }
}

impl std::error::Error for AbiMismatch {}

/// Checks the host ABI before the guest does any work. Call this from
/// `natcatty_init` and fail init when it returns an error.
pub fn ensure_compatible_abi() -> Result<(), AbiMismatch> {
    let host = abi_version();
    if host == ABI_VERSION {
        Ok(())
    } else {
        Err(AbiMismatch::HostAbi(host))
    }
}

/// The guest export the host reads before calling init.
#[no_mangle]
pub extern "C" fn natcatty_abi_version() -> i32 {
    ABI_VERSION
}
